// Fill only NON-SECRET IDs and the EspoCRM URL used by the single custom AGE summary GET.
// All normal records are read with @traien/n8n-nodes-espocrm@1.4.0 and
// @renatoascencio/n8n-nodes-chatwoot@0.9.0. NO contact/campaign sends.
const cfg={
  espoCampaignId:'REPLACE_ESPO_CAMPAIGN_ID',
  chatwootCampaignDisplayId:'REPLACE_CHATWOOT_DISPLAY_ID',
  espoUrl:'https://REPLACE_ESPO_HOST',
};
if(!cfg.espoCampaignId||cfg.espoCampaignId.includes('REPLACE_')||
   !/^[1-9][0-9]*$/.test(cfg.chatwootCampaignDisplayId)||
   cfg.espoUrl.includes('REPLACE_'))throw new Error('CONFIG_REQUIRED: set non-secret EspoCRM Campaign ID, Chatwoot display ID, and EspoCRM HTTPS URL');
if(new URL(cfg.espoUrl).protocol!=='https:')throw new Error('HTTPS required');
return [{json:{...cfg,chatwootCampaignId:Number(cfg.chatwootCampaignDisplayId)}}];

const crm=$('EspoCRM - Get Campaign').first().json;
const summary=$('AGE Custom Summary - HTTP Fallback').first().json;
const chatwoot=$('Chatwoot - Get Campaign').first().json;
const metrics=$('Chatwoot - Get Campaign Metrics').first().json;
if(!crm||!crm.id||!summary||typeof summary!=='object'||!chatwoot||typeof chatwoot!=='object'||!Number.isInteger(metrics.audience))throw new Error('One of the authenticated read-only API responses is incomplete');
return [{json:{checkedAt:new Date().toISOString(),mode:'READ_ONLY',
 espoCampaignReadable:true,espoCampaignActive:crm.status==='Active',
 ageCustomSummaryReadable:true,chatwootCampaignReadable:true,
 chatwootAnalyticsReadable:true,chatwootAudienceCount:metrics.audience,
 chatwootDelivered:metrics.delivered??null,
 chatwootFailed:metrics.failed??null,
 crmEventWriteAuthorized:false,liveSendAttempted:false}}];
